-- create "intent_replay_evaluations" table
CREATE TABLE "intent_replay_evaluations" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "bot_id" bigint NOT NULL,
  "mode" text NOT NULL,
  "name" text NOT NULL DEFAULT '',
  "note" text NOT NULL DEFAULT '',
  "changed" boolean NOT NULL DEFAULT false,
  "before_run" jsonb NOT NULL DEFAULT '{}',
  "after_run" jsonb NOT NULL DEFAULT '{}',
  "parameters" jsonb NOT NULL DEFAULT '{}',
  "cost" jsonb NOT NULL DEFAULT '{}',
  "reproduction" jsonb NOT NULL DEFAULT '{}',
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "decision_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "intent_replay_evaluations_intent_decisions_intent_replay_evalua" FOREIGN KEY ("decision_id") REFERENCES "intent_decisions" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "intent_replay_evaluations_mode_check" CHECK (mode = ANY (ARRAY['recalculate'::text, 'model'::text]))
);
-- create index "intent_replay_evaluations_bot_id_id" to table: "intent_replay_evaluations"
CREATE INDEX "intent_replay_evaluations_bot_id_id" ON "intent_replay_evaluations" ("bot_id", "id");
-- create index "intent_replay_evaluations_decision" to table: "intent_replay_evaluations"
CREATE INDEX "intent_replay_evaluations_decision" ON "intent_replay_evaluations" ("decision_id");

